import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"kimi acp 子命令","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/reference/kimi-acp.md","filePath":"zh/kimi-code-cli/reference/kimi-acp.md"}`),a={name:`kimi-code-cli/reference/kimi-acp.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="kimi-acp-子命令" tabindex="-1"><code>kimi acp</code> 子命令 <a class="header-anchor" href="#kimi-acp-子命令" aria-label="Permalink to “kimi acp 子命令”">​</a></h1><p><code>kimi acp</code> 把 Kimi Code CLI 切换到 <strong>ACP (Agent Client Protocol)</strong> 模式：在标准输入/输出上以 JSON-RPC 形式与 ACP 客户端（如 Zed、JetBrains AI Chat 等）对话，让 IDE 直接驱动 kimi 的会话、prompt 与工具调用。</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acp</span></span></code></pre></div><p>启动后命令不会打印任何 banner，立刻等待 ACP 客户端在 stdin 上发出 <code>initialize</code> 请求。日志会写到标准错误（以及 <code>~/.kimi-code/logs/</code> 下的诊断日志），所以 ACP 通道本身保持干净。</p><div class="tip custom-block"><p class="custom-block-title">谁会调用它？</p><p>你通常不需要手动跑 <code>kimi acp</code>——这个命令是给 IDE 的子进程入口准备的。IDE 端的配置见<a href="/code/docs/kimi-code-cli/guides/ides.html">在 IDE 中使用</a>。</p></div><h2 id="能力矩阵" tabindex="-1">能力矩阵 <a class="header-anchor" href="#能力矩阵" aria-label="Permalink to “能力矩阵”">​</a></h2><p>下表列出当前 ACP 适配层声明的能力。<code>agentCapabilities</code> 字段在 <code>initialize</code> 响应里完整返回，IDE 端可据此调整 UI。</p><table tabindex="0"><thead><tr><th>能力</th><th>取值</th><th>说明</th></tr></thead><tbody><tr><td><code>promptCapabilities.image</code></td><td><code>true</code></td><td>支持 ACP <code>image</code> 内容块（base64 + mimeType）</td></tr><tr><td><code>promptCapabilities.audio</code></td><td><code>false</code></td><td>暂不支持音频 prompt</td></tr><tr><td><code>promptCapabilities.embeddedContext</code></td><td><code>true</code></td><td>客户端可发送 <code>resource</code>/<code>resource_link</code> 嵌入式资源块，文本内容会以 <code>&lt;resource uri=&quot;...&quot;&gt;...&lt;/resource&gt;</code> 形式注入 prompt；blob 资源被丢弃并写 warn</td></tr><tr><td><code>mcpCapabilities.http</code></td><td><code>true</code></td><td>转发 IDE 配置的 HTTP MCP 服务</td></tr><tr><td><code>mcpCapabilities.sse</code></td><td><code>true</code></td><td>转发 IDE 配置的旧式 SSE MCP 服务</td></tr><tr><td><code>loadSession</code></td><td><code>true</code></td><td>支持 <code>session/load</code> 续接已有会话，加载时会同步回放历史</td></tr><tr><td><code>sessionCapabilities.list</code></td><td><code>{}</code></td><td>支持 <code>session/list</code> 枚举当前用户的会话</td></tr></tbody></table><h2 id="acp-方法覆盖" tabindex="-1">ACP 方法覆盖 <a class="header-anchor" href="#acp-方法覆盖" aria-label="Permalink to “ACP 方法覆盖”">​</a></h2><p>规范把方法分为<strong>稳定</strong>面和仍在演化的<strong>不稳定</strong>面（<code>@agentclientprotocol/sdk@0.23.0</code> 中以 <code>unstable_*</code> 前缀挂载的 handler）。两部分稳定性保证完全不同——稳定面是任何生产 ACP 客户端都会用到的方法，不稳定面覆盖实验性扩展（inline-edit 预测、document 缓冲区同步、provider 管理、elicitation 等），因此分开追踪。</p><p><strong>概览：稳定面 agent-side 实现 10/12（83%）+ client reverse-RPC 实现 4/9（44%）；不稳定面只接入了 <code>session/set_model</code>（1/19）。</strong> 任何正常 agent 流程所需的方法（initialize → auth → new/load/resume → prompt → cancel + 文件 I/O + 工具审批）都已实现。</p><h3 id="稳定面-agent-side-—-ide-→-agent-10-12" tabindex="-1">稳定面 agent-side — IDE → agent（10 / 12） <a class="header-anchor" href="#稳定面-agent-side-—-ide-→-agent-10-12" aria-label="Permalink to “稳定面 agent-side — IDE → agent（10 / 12）”">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><code>initialize</code></td><td>是</td><td>版本协商；返回 <code>agentInfo: { name: &#39;Kimi Code CLI&#39;, version }</code>、能力矩阵、<code>authMethods</code></td></tr><tr><td><code>authenticate</code></td><td>是</td><td>校验 <code>method_id=&#39;login&#39;</code>；token 缺失返回 <code>authRequired (-32000)</code>，未知 id 返回 <code>invalidParams (-32602)</code></td></tr><tr><td><code>session/new</code></td><td>是</td><td>接受 <code>cwd</code> / <code>mcpServers</code>，返回 <code>configOptions[]</code></td></tr><tr><td><code>session/load</code></td><td>是</td><td>恢复磁盘会话并把历史以 <code>session/update</code> 同步回放</td></tr><tr><td><code>session/resume</code></td><td>是</td><td><code>session/load</code> 的轻量兄弟方法，跳过历史回放</td></tr><tr><td><code>session/prompt</code></td><td>是</td><td>接受 <code>text</code> / <code>image</code> / <code>resource</code> / <code>resource_link</code> 内容块，流式输出 <code>agent_message_chunk</code></td></tr><tr><td><code>session/cancel</code></td><td>是</td><td>中断当前 turn</td></tr><tr><td><code>session/list</code></td><td>是</td><td>枚举磁盘会话（通过 <code>sessionCapabilities.list = {}</code> 公告）</td></tr><tr><td><code>session/set_mode</code></td><td>是</td><td>兼容路径，与 <code>set_config_option({configId:&#39;mode&#39;})</code> 走同一 dispatcher</td></tr><tr><td><code>session/set_config_option</code></td><td>是</td><td>统一的 model / thinking / mode picker 分发</td></tr><tr><td><code>session/close</code></td><td>否</td><td></td></tr><tr><td><code>logout</code></td><td>否</td><td></td></tr></tbody></table><h3 id="稳定面-client-side-reverse-rpc-—-agent-→-ide-4-9" tabindex="-1">稳定面 client-side reverse-RPC — agent → IDE（4 / 9） <a class="header-anchor" href="#稳定面-client-side-reverse-rpc-—-agent-→-ide-4-9" aria-label="Permalink to “稳定面 client-side reverse-RPC — agent → IDE（4 / 9）”">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><code>session/update</code></td><td>是</td><td>流式推送 <code>agent_message_chunk</code> / <code>tool_call*</code> / <code>plan</code> / <code>config_option_update</code> / <code>available_commands_update</code></td></tr><tr><td><code>session/request_permission</code></td><td>是</td><td>工具审批和问题 elicitation 共用此通道</td></tr><tr><td><code>fs/read_text_file</code></td><td>是</td><td>kaos 层文件读取路由到客户端（通过 <code>fsCapabilities</code> 公告）</td></tr><tr><td><code>fs/write_text_file</code></td><td>是</td><td>kaos 层文件写入路由到客户端</td></tr><tr><td><code>terminal/create</code> · <code>output</code> · <code>release</code> · <code>kill</code> · <code>wait_for_exit</code></td><td>否</td><td>终端 reverse-RPC 未接，shell 命令走本地执行</td></tr></tbody></table><h3 id="不稳定面-1-19" tabindex="-1">不稳定面（1 / 19） <a class="header-anchor" href="#不稳定面-1-19" aria-label="Permalink to “不稳定面（1 / 19）”">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><code>session/set_model</code></td><td>是</td><td>兼容路径，等价于 <code>set_config_option({configId:&#39;model&#39;})</code></td></tr><tr><td>其余 18 个方法</td><td>否</td><td>包括 session 生命周期扩展、缓冲区同步、inline-edit 预测、provider 管理等</td></tr></tbody></table><p>上述未列出的方法一律返回 <code>methodNotFound</code>。</p><h2 id="mcp-转发" tabindex="-1">MCP 转发 <a class="header-anchor" href="#mcp-转发" aria-label="Permalink to “MCP 转发”">​</a></h2><p>ACP 客户端在 <code>session/new</code> 或 <code>session/load</code> 中提供 <code>mcpServers</code> 时，适配层做如下转换：</p><ul><li><code>http</code> → kimi 的 <code>transport: &#39;http&#39;</code> 配置</li><li><code>stdio</code> → kimi 的 <code>transport: &#39;stdio&#39;</code> 配置</li><li><code>sse</code> → kimi 的 <code>transport: &#39;sse&#39;</code> 配置</li><li><code>acp</code> → 丢弃并写一条 warn 日志</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/guides/ides.html">在 IDE 中使用</a> — Zed / JetBrains 配置步骤和故障排查</li><li><a href="/code/docs/kimi-code-cli/reference/kimi-command.html">kimi 命令参考</a> — 完整子命令列表</li></ul>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};